def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0.0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_prev:
                    strong_prev = float(bid)

    if not alive:
        return max(0.0, min(budget, 8.0))

    contested = supply < WATER_REQ * 2
    danger = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if critical:
        target = max(92.0, strong_prev + 2.0)
    elif contested and danger:
        target = max(82.0, strong_prev + 1.5)
    elif contested:
        if strong_prev >= 120.0:
            target = 36.0 if hp >= 5 and no_water == 0 else 88.0
        elif strong_prev >= 90.0:
            target = 68.0 if hp >= 5 and no_water == 0 else 84.0
        else:
            target = max(58.0, strong_prev + 1.5)
    else:
        if danger:
            target = max(60.0, strong_prev * 0.8 if strong_prev > 0 else 60.0)
        else:
            target = 22.0 if strong_prev >= 90.0 else 34.0

    if budget < target:
        if critical:
            return max(0.0, budget)
        return max(0.0, min(budget, max(12.0, budget * 0.7)))

    return max(0.0, min(budget, float(target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, bid low to conserve budget
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday bids from traces for immediate pressure estimate
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    my_hp = my_status.get('hp', 0.0)
    my_budget = my_status.get('budget', 0.0)

    # Estimate how many water units are likely available/needed
    # (Supply is total water; water requirement is per unit need)
    # Use int() to avoid float index issues; also keep it only for scaling.
    supply_units = int(supply / float(WATER_REQ)) if WATER_REQ else 0
    if supply_units <= 0:
        supply_units = 1

    # Base aggressiveness from observed meta: survival correlated with ~90+ bids.
    # If someone bid very high yesterday, we must not underbid.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure day
        if my_hp > 3:
            target = DAILY_SALARY * 0.32
        else:
            target = DAILY_SALARY * 0.92
    else:
        # Moderate pressure day: try to beat typical survival bids without overpaying
        # Use a function of remaining budget and supply units.
        budget_pressure = 0.0
        if my_budget > 0:
            budget_pressure = min(1.0, my_budget / (DAILY_SALARY * 1.2))
        target = max(DAILY_SALARY * 0.55, highest_prev_bid + 2.0)
        # If supply units are low, increase bid; if high, decrease slightly
        if supply_units <= 1:
            target *= 1.15
        elif supply_units >= 2:
            target *= 0.95
        target *= (0.85 + 0.15 * budget_pressure)

    # If very low budget or low hp, bid up to avoid death
    if my_hp <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    if my_budget <= DAILY_SALARY * 0.35:
        target = min(my_budget, max(target, DAILY_SALARY * 0.6))

    # Final cap by budget
    bid = float(min(my_budget, target))

    # Ensure bid is non-negative
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return max(1.0, min(my_budget, DAILY_SALARY * 0.1))

    yesterday_bids = []
    opponent_desperation_score = 0

    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

            if opp_data['hp'] <= 2:
                opponent_desperation_score += 2
            elif opp_data['hp'] <= 5:
                opponent_desperation_score += 1

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = DAILY_SALARY * 0.6 

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 1.2
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 1.0
    elif my_hp <= 7:
        base_bid = DAILY_SALARY * 0.8
    else:
        base_bid = DAILY_SALARY * 0.65

    if current_day >= EPISODE_DAYS - 2:
        base_bid *= 1.2
    elif current_day <= 3:
        if my_hp > 7:
            base_bid *= 0.85

    if current_supply <= WATER_REQ + 2:
        base_bid *= 1.1
    elif current_supply >= WATER_REQ * 1.5:
        if my_hp > 5:
            base_bid *= 0.95

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            if my_hp <= 5:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    if len(alive_opponents) > 0 and opponent_desperation_score >= len(alive_opponents):
        if my_hp <= 5:
            base_bid *= 1.15
        elif my_hp > 7:
            base_bid *= 0.9

    final_bid = max(1.0, min(base_bid, my_budget))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents) + 1

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        bid = DAILY_SALARY * 1.1
    else:
        avg_prev = sum(prev_bids) / len(prev_bids)
        max_prev = max(prev_bids)
        bid = max(avg_prev, max_prev) * 1.05

    if my_status['hp'] < 4:
        bid = max(bid, DAILY_SALARY * 1.5)

    if supply < WATER_REQ * num_alive:
        bid = max(bid, DAILY_SALARY * 1.2)

    return float(min(my_status['budget'], bid))
